{
  "name": "opencode-glm-clipboard",
  "version": "2.2.0",
  "description": "OpenCode plugin that converts pasted clipboard data URLs to temp files for GLM models",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/WilfredLemus/opencode-glm-clipboard.git"
  },
  "homepage": "https://github.com/WilfredLemus/opencode-glm-clipboard#readme",
  "bugs": {
    "url": "https://github.com/WilfredLemus/opencode-glm-clipboard/issues"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "opencode-glm-clipboard": "scripts/install-opencode-glm-clipboard.js"
  },
  "files": [
    "dist/",
    "scripts/",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test": "vitest run"
  },
  "keywords": [
    "opencode",
    "plugin",
    "glm",
    "clipboard",
    "image",
    "mcp"
  ],
  "author": "wilfredlemus",
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.150"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.150",
    "@types/node": "^24.6.2",
    "typescript": "^5.9.3",
    "vitest": "^3.2.4"
  }
}
